 const drawEmployees=rows=>{$('#staff-list').innerHTML=table([{label:'Colaborador',render:r=>`<b>${esc(r.legalName)}</b><div class="branch-meta">${esc(r.employeeCode)} · ${esc(r.positionTitle)}</div>`},{label:'Estado',render:r=>badge(r.status)},{label:'Código',key:'employeeCode'},{label:'Detalle',render:r=>`<button class="text-button" data-employee-detail="${esc(r.id)}" aria-label="Abrir ficha de ${esc(r.legalName)}">Abrir ficha →</button>`},{label:'Acción',render:r=>state.permissions.includes('staff.manage')&&r.status==='active'?`<button class="text-button" data-suspend="${esc(r.id)}:${esc(r.version)}">Suspender</button>`:'—'}],rows);$('#staff-list').querySelectorAll('[data-employee-detail]').forEach(b=>b.onclick=()=>showEmployee(b.dataset.employeeDetail));$('#staff-list').querySelectorAll('[data-suspend]').forEach(b=>b.onclick=async()=>{const [id,version]=b.dataset.suspend.split(':');const reason=prompt('Motivo del cambio de estado (mínimo 10 caracteres):');if(!reason||reason.trim().length<10)return;try{await request(`/branches/${state.branchId}/staff/employees/${id}/transition`,{method:'POST',data:{commandId:crypto.randomUUID(),expectedVersion:Number(version),status:'suspended',effectiveOn:today(),reason:reason.trim()}});toast('Estado del colaborador actualizado.');await staffPage()}catch(e){showError(e)}}) };drawEmployees(staff);
