 const list=$('#register-list');list.innerHTML=table([{label:'Caja',key:'code'},{label:'Estado',render:r=>badge(r.openSessionId?'Abierta':'Cerrada')},{label:'Sesión',render:r=>r.openSessionId?`<button class="text-button" data-open-session="${esc(r.openSessionId)}">Ver caja →</button>`:'—'}],registers);list.querySelectorAll('[data-open-session]').forEach(b=>b.onclick=()=>showSession(b.dataset.openSession));$('#content').querySelectorAll('[data-cash-review]').forEach(b=>b.onclick=()=>showSession(b.dataset.cashReview,true));
