 async function showSalePayments(saleId){try{const result=arr(await request(`${base}/sales/${saleId}/payments`)),el=$('#sale-payments-detail');el.innerHTML=`<div class="section-head compact"><h3>Intentos de cobro</h3><button type="button" class="secondary" data-sale-receipt>Comprobante interno PDF · NO FISCAL</button></div>${table([{label:'Fecha',render:r=>new Date(r.createdAt).toLocaleString()},{label:'Método',key:'method'},{label:'Modo',render:r=>r.mode==='simulated'?'Simulado':'Manual'},{label:'Importe',render:r=>`$${esc(r.amountUsd)}`},{label:'Estado',render:r=>badge(r.status)},{label:'Referencia',key:'evidenceReference'},{label:'Acción',render:r=>r.status==='unknown'&&state.permissions.includes('payment.resolve')?`<button class="text-button" data-resolve-payment="${esc(r.id)}">Conciliar resultado</button>`:'—'}],result)}`;el.querySelector('[data-sale-receipt]').onclick=async()=>{try{const blob=await request(`${base}/sales/${saleId}/receipt.pdf`),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`comprobante-${saleId}.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){showError(e)}};await renderPointRefunds(saleId,el);el.querySelectorAll('[data-resolve-payment]').forEach(b=>b.onclick=async()=>{const outcome=prompt('Resultado confirmado o rechazado según la terminal: confirmed / declined');if(!['confirmed','declined'].includes(outcome))return;const evidenceReference=prompt('Referencia de terminal o comprobante:');if(!evidenceReference?.trim())return;try{await request(`${base}/payments/${b.dataset.resolvePayment}/resolve`,{method:'POST',data:{commandId:crypto.randomUUID(),outcome,evidenceReference:evidenceReference.trim()}});toast('Resultado de pago conciliado.');await cashPage()}catch(e){showError(e)}})}catch(e){showError(e)}}
