function assetStatusForm(type,item){if(!state.permissions.includes('infrastructure.propose'))return '';const id=item.id,current=type==='dispenser'?item.physicalStatus:item.status;return `<div class="report-box space-top"><h3>Estado operativo</h3><form class="filters" id="asset-status-form"><select name="status"><option value="active" ${current==='active'?'selected':''}>Activo</option><option value="maintenance" ${current==='maintenance'?'selected':''}>En mantenimiento</option><option value="offline" ${current==='offline'?'selected':''}>Fuera de servicio</option></select><input name="reason" minlength="3" maxlength="500" placeholder="Motivo del cambio (mínimo 3 caracteres)" required><button class="secondary">Guardar estado</button></form></div>`}
