 $('#content').innerHTML=`<p class="page-subtitle">Daños, derrames, lesiones, pérdidas y otros incidentes. Una incidencia no confirma por sí sola una pérdida contable.</p><div class="toolbar"><div class="filters"><input id="incident-search" maxlength="100" placeholder="Buscar código, tipo, activo o descripción"><select id="incident-status"><option value="">Todos los estados</option>${['reported','assessed','in_progress','resolved','closed'].map(x=>`<option value="${x}">${x.replaceAll('_',' ')}</option>`).join('')}</select><select id="incident-severity"><option value="">Todas las severidades</option>${['low','medium','high','critical'].map(x=>`<option value="${x}">${x==='low'?'Baja':x==='medium'?'Media':x==='high'?'Alta':'Crítica'}</option>`).join('')}</select><button class="secondary" id="incident-filter">Filtrar</button></div><button class="primary" id="new-incident">＋ Nueva incidencia</button></div><div id="quick-form" class="card report-box" hidden></div><article class="card" id="incident-list"></article><button class="secondary space-top" id="incident-more" hidden>Mostrar más incidencias</button><article id="incident-detail" class="card report-box space-top" hidden></article>`;
